def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        if i == len(line):
            # End of line - add the last field
            fields.append("")
            break

        if line[i] == '"':
            # Quoted field
            field = ""
            i += 1
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what comes next
                        if i == len(line):
                            fields.append(field)
                            break
                        elif line[i] == ',':
                            fields.append(field)
                            i += 1
                            break
                        else:
                            return None
                else:
                    field += line[i]
                    i += 1
            else:
                # Loop ended without finding closing quote
                return None
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    return None
                field += line[i]
                i += 1

            fields.append(field)
            if i < len(line):
                i += 1

    return fields

